async function checkpointActiveTask(
  input: CheckpointActiveTaskInput,
): Promise<CheckpointActiveTaskOutput> {
  const checkpointId = input.checkpointId.trim();
  if (checkpointId.length === 0 || checkpointId.length > 200) {
    throw new ContinuityServiceError("VALIDATION_ERROR", "checkpointId must contain between 1 and 200 characters");
  }
  const summary = input.task.state === "clear" ? input.task.outcome.trim() : input.task.summary.trim();
  if (summary.length === 0 || summary.length > MAX_ACTIVE_TASK_TEXT_CHARS) {
    throw new ContinuityServiceError(
      "VALIDATION_ERROR",
      `task summary must contain between 1 and ${MAX_ACTIVE_TASK_TEXT_CHARS} characters`,
    );
  }
  if (input.task.state !== "clear") {
    const nextStep = input.task.nextStep.trim();
    if (nextStep.length === 0 || nextStep.length > MAX_ACTIVE_TASK_TEXT_CHARS) {
      throw new ContinuityServiceError(
        "VALIDATION_ERROR",
        `task next step must contain between 1 and ${MAX_ACTIVE_TASK_TEXT_CHARS} characters`,
      );
    }
  }
  if ((input.task.details?.length ?? 0) > MAX_ACTIVE_TASK_DETAILS_CHARS) {
    throw new ContinuityServiceError(
      "VALIDATION_ERROR",
      `task details must contain at most ${MAX_ACTIVE_TASK_DETAILS_CHARS} characters`,
    );
  }

  const paths = resolveBoundContinuityWorkspace(input);
  return withWorkspaceMutationLock(paths, async () => {
    const before = await readCurrent(paths);
    if (before.kind === "malformed") throw new ContinuityServiceError("CONTINUITY_MALFORMED", before.message);

    const eventId = checkpointEventId(paths.workspace.key, checkpointId);
    const events = await readAllEvents(paths);
    if (events.kind === "malformed") throw new ContinuityServiceError("CONTINUITY_MALFORMED", events.message);
    const existing = events.kind === "ok" ? events.events.find((event) => event.id === eventId) : undefined;
    const details = checkpointDetails(input.task);
    if (existing && !checkpointEventMatches(existing, input.task, details)) {
      throw new ContinuityServiceError(
        "VALIDATION_ERROR",
        `checkpointId ${checkpointId} was already used for different task content`,
      );
    }
    if (input.task.state === "clear" && before.kind === "missing" && !existing) {
      throw new ContinuityServiceError("CONTINUITY_NOT_INITIALIZED", "Cannot clear an active task before Continuity exists");
    }
    if (input.task.state === "clear" && before.kind === "ok" && before.value.active_task === null && !existing) {
      throw new ContinuityServiceError("VALIDATION_ERROR", "No active task is available to clear");
    }

    const priorTask = before.kind === "ok" ? before.value.active_task : null;
    const eventInput: EventInput = {
      type: input.task.state === "clear" ? "correction" : "next_action",
      status: "active",
      summary: input.task.state === "clear" ? input.task.outcome : input.task.summary,
      details,
      supersedes:
        input.task.state !== "clear" && priorTask && priorTask.event_id !== eventId ? [priorTask.event_id] : [],
      resolves: input.task.state === "clear" && priorTask ? [priorTask.event_id] : [],
      related_events: priorTask ? [priorTask.event_id] : [],
    };
    const event =
      existing ??
      (await recordEvent(paths, eventInput, {
        source: boundEventSource(input.binding, input.source),
        now: input.now,
        id: () => eventId,
      }));

    const afterRecord = await readCurrent(paths);
    if (afterRecord.kind !== "ok") {
      throw new ContinuityServiceError("CONTINUITY_MALFORMED", afterRecord.message);
    }
    const desired: ActiveTask | null =
      input.task.state === "clear"
        ? null
        : activeTaskSchema.parse({
            event_id: event.id,
            recorded_at: event.effective_at ?? event.created_at,
            summary: input.task.summary,
            state: input.task.state,
            next_step: input.task.nextStep,
          });
    const taskChanged = JSON.stringify(afterRecord.value.active_task) !== JSON.stringify(desired);
    const nextInput = currentFrameInput(afterRecord.value);
    nextInput.active_task = desired;
    nextInput.next_actions = nextInput.next_actions.filter((item) => item.event_id !== event.id);
    const changed = taskChanged || nextInput.next_actions.length !== afterRecord.value.next_actions.length;
    const frame = changed
      ? await updateCurrent(paths, nextInput, { now: input.now })
      : afterRecord.value;

    return {
      paths,
      workspace: paths.workspace,
      event,
      frame,
      rendered: renderContinuityFrame(frame),
      changed,
      binding: workContextBindingView(input.binding),
    };
  }, { now: input.now });
}

type CheckpointActiveTaskInput = BoundContinuityMutationOptions & {
  checkpointId: string;
  task:
    | {
        state: ActiveTaskState;
        summary: string;
        nextStep: string;
        details?: string;
      }
    | {
        state: "clear";
        outcome: string;
        details?: string;
      };
  source?: EventSource;
  now?: Clock;
};

type BoundContinuityMutationOptions = {
  binding: WorkContextBinding;
  stateRoot?: string;
  bindingNow?: Clock;
};

type CaptureCommandResultOptions = {
  argv: string[];
  producer: string;
  binding: WorkContextBinding;
  stateRoot?: string;
  cwd?: string;
  now?: Clock;
};

type WorkContextBinding = {
  version: 1;
  id: string;
  status: "active" | "superseded";
  host: string;
  session_id: string;
  bound_at: string;
  last_seen_at: string;
  expires_at: string;
  collaboration_space: WorkspaceRef;
  provenance: {
    kind: "host_lifecycle" | "operator_rebind";
    lifecycle: string;
    observed_cwd: string;
  };
  superseded_by?: string;
  superseded_at?: string;
};

async function runBrowserCli(args: string[], dependencies: BrowserCliDependencies): Promise<number> {
  const flags = parseBrowserFlags(args);
  const write = dependencies.stdout ?? ((value: string) => process.stdout.write(value));
  const anvilHome = resolve(dependencies.anvilHome ?? join(dependencies.homeDir ?? homedir(), ".anvil"));
  const command = flags._[0];
  if (!command || command === "help") {
    write(`${browserCliUsage()}\n`);
    return 0;
  }
  if (command === "install") {
    output(await installCommand(flags, dependencies, anvilHome), flags.json, write);
    return 0;
  }
  if (command === "status" && flags._.length === 1) {
    output(await readCapabilityStatus(anvilHome, dependencies.anvilCommand, dependencies), flags.json, write);
    return 0;
  }
  if (command === "doctor" && flags._.length === 1) {
    const result = await doctorCommand(dependencies, anvilHome);
    output(result, flags.json, write);
    return (result as { ok: boolean }).ok ? 0 : 1;
  }
  if (command === "mcp" && flags._[1] === "serve" && flags._.length === 2) {
    return (dependencies.serveMcp ?? serveBrowserMcp)({ mode: browserMode(flags.networkMode), anvilHome });
  }
  if (command === "upgrade") {
    output(await upgradeCommand(flags, dependencies, anvilHome), flags.json, write);
    return 0;
  }
  if (command === "uninstall") {
    output(await uninstallCommand(flags, dependencies, anvilHome), flags.json, write);
    return 0;
  }
  throw cliError(browserCliUsage());
}

async function main(): Promise<void> {
  if (command.length === 0 || command[0] === "--help" || command[0] === "help") {
    process.stdout.write(`${usage()}\n`);
    return;
  }

  if (command[0] === "manifest") {
    const { runManifestCli } = await import("./manifest.ts");
    await runManifestCli(command.slice(1));
    return;
  }

  if (
    command[0] === "codex" &&
    (command[1] === "context-hook" || command[1] === "session-start-hook")
  ) {
    await runContextHook();
    return;
  }

  if (command[0] === "continuity" && command[1] === "read") {
    await continuityRead(command.slice(2));
    return;
  }

  if (command[0] === "work-context" && command[1] === "read") {
    await workContextRead(command.slice(2));
    return;
  }

  if (command[0] === "work-context" && command[1] === "doctor") {
    await workContextDoctor(command.slice(2));
    return;
  }

  if (command[0] === "continuity" && command[1] === "doctor") {
    await continuityDoctor(command.slice(2));
    return;
  }

  if (command[0] === "continuity" && command[1] === "routing-audit") {
    await continuityRoutingAudit(command.slice(2));
    return;
  }

  if (command[0] === "continuity" && command[1] === "init-default") {
    await continuityInitDefault(command.slice(2));
    return;
  }

  if (command[0] === "brain" && command[1] === "log") {
    await brainLog(command.slice(2));
    return;
  }

  if (command[0] === "brain" && command[1] === "usage") {
    await brainUsage(command.slice(2));
    return;
  }

  if (command[0] === "brain" && command[1] === "metrics") {
    await brainMetrics(command.slice(2));
    return;
  }

  if (command[0] === "brain" && command[1] === "dashboard") {
    await brainDashboard(command.slice(2));
    return;
  }

  if (command[0] === "skills" && command[1] === "log") {
    await skillsLog(command.slice(2));
    return;
  }

  if (command[0] === "skills" && command[1] === "invocations") {
    await skillsInvocations(command.slice(2));
    return;
  }

  if (command[0] === "skills" && command[1] === "audit-sample") {
    await skillsAuditSample(command.slice(2));
    return;
  }

  if (command[0] === "tool-result" && command[1] === "capture") {
    await captureToolResult(command.slice(2));
    return;
  }

  if (command[0] === "browser") {
    const exitCode = await runBrowserCli(command.slice(1), {
      anvilCommand: currentFile,
      ...(process.env.ANVIL_HOME ? { anvilHome: process.env.ANVIL_HOME } : {}),
    });
    if (exitCode !== 0) process.exitCode = exitCode;
    return;
  }

  if (command[0] === "mcp" && command[1] === "serve") {
    await runAnvilMcpServer();
    return;
  }

  fail(usage());
}

